package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyClaimStatus {
    public void apply(@Val ValidClaimStatus request, @Val Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering, Out<ClaimNumber> number)
            throws ClaimStatusRefusedException {
        number.set(change(request, claim, sheets, people, rates, periods, settings, numbering));
    }

    /** Applies a status change to the claim by the rules of a single change, returning its number;
     *  throws, leaving the claim as it is, when the change is refused. Bulk settle uses it too. */
    static ClaimNumber change(ValidClaimStatus request, Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering)
            throws ClaimStatusRefusedException {
        RoundingMode rounding = Rounding.of(claim, settings.policyDate(claim.getSheetId()));
        if (periods.isClosed(claim.getSheetId(), claim.getDate())) {
            throw new ClaimStatusRefusedException("No claim dated inside a closed period can change status");
        }
        boolean steward = Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()));
        if (request.decision() == ValidClaimStatus.Decision.NONE) {
            // Opening, settling and voiding are each taken only by the roles the sheet's permission allows.
            String action = switch (request.target()) {
                case OPEN -> "open";
                case SETTLED -> "settle";
                default -> "void";
            };
            if (!settings.allows(claim.getSheetId(), request.user(), action)) {
                throw new ClaimStatusRefusedException("Your role may not " + action + " a claim on this sheet");
            }
        }
        if (request.decision() != ValidClaimStatus.Decision.NONE) {
            // Only a steward approves or rejects, and only a PENDING claim.
            if (claim.getStatus() != ClaimStatus.PENDING) {
                throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
            }
            if (!steward) {
                throw new ClaimStatusRefusedException("Only a steward can approve or reject a PENDING claim");
            }
        } else if (!claim.getStatus().canBecome(request.target())) {
            throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
        }
        if (request.target() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(request.user())) {
            // Four eyes: the user who opened a claim cannot settle (or approve) it.
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        if (request.target() == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until its deferred-until date");
        }
        ClaimStatus target = request.target();
        if (target == ClaimStatus.SETTLED && claim.getProofs() == 0) {
            // Above the proof threshold in force on the claim's date a claim needs a proof to be settled or approved,
            // judged on its due as shown (before the clerk limit is considered); a due of n/a is within any threshold.
            BigDecimal threshold = settings.proofThreshold(claim.getSheetId(), claim.getDate());
            BigDecimal due = shownDue(claim, sheets, people, rates, settings, rounding);
            if (threshold != null && due != null && due.compareTo(threshold) > 0) {
                throw new ClaimStatusRefusedException("A claim whose due is above the proof threshold needs a proof to be settled");
            }
        }
        if (target == ClaimStatus.SETTLED && request.decision() == ValidClaimStatus.Decision.NONE && !steward) {
            // A clerk settles only within the sheet's clerk limit, judged on the claim's due as shown;
            // a due of n/a is within any limit.
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            BigDecimal due = shownDue(claim, sheets, people, rates, settings, rounding);
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                // Above the clerk limit the claim awaits a steward's approval.
                target = ClaimStatus.PENDING;
            }
        }
        if (target == ClaimStatus.OPEN && request.decision() == ValidClaimStatus.Decision.NONE) {
            claim.setNumber(numbering.next(claim.getSheetId(), claim.getDate()));
            claim.setOpenedBy(request.user());
        }
        // A voided claim keeps its number; numbers are never reused.
        ClaimNumber number = new ClaimNumber(claim.getNumber());
        if (target == ClaimStatus.SETTLED) {
            // Settling (or approving) fixes the due: the figure a statement bound it to (never while PENDING), else its amount (raised to the floor)
            // at the rate in force on the claim's date, with its late charge as of today frozen in; with no
            // figure it stays live (n/a until a rate is set).
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            BigDecimal figure = claim.isBound() && claim.getStatedDue() != null ? claim.getStatedDue()
                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
                    settings.floor(claim.getSheetId(), claim.getDate()), rounding);
            claim.setSettledDue(LateCharge.withCharge(claim, figure, on -> settings.latePct(claim.getSheetId(), on),
                    sheets.today(claim.getSheetId()), rounding));
        }
        // A rejected claim is OPEN again, so bound again by the last statement if it included it.
        claim.setStatus(target);
        return number;
    }

    /** The claim's due as shown: fixed (settled or bound), else its live figure with its late charge as of today; null for n/a. */
    private static BigDecimal shownDue(Claim claim, Sheets sheets, People people, Rates rates, Settings settings,
            RoundingMode rounding) {
        String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
        BigDecimal fixed = ClaimResponse.fixedDue(claim);
        BigDecimal figure = fixed != null || claim.isBound() ? fixed
                : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
                settings.floor(claim.getSheetId(), claim.getDate()), rounding);
        return LateCharge.withCharge(claim, figure, on -> settings.latePct(claim.getSheetId(), on),
                sheets.today(claim.getSheetId()), rounding);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.person.People;
import net.officefloor.plugin.variable.Val;

public class AuditClaimStatus {
    public void audit(@Val ValidClaimStatus request, @Val Claim claim, @Val ClaimNumber number, People people, Audit audit, @Val RollupFigures before, Rollup rollup, ClaimLog log) {
        record(request, claim, number, people, audit, before, rollup, log);
    }

    /** Logs and audits a status change that went through, as a single change does. Bulk settle uses it too. */
    static void record(ValidClaimStatus request, Claim claim, ClaimNumber number, People people, Audit audit, RollupFigures before, Rollup rollup, ClaimLog log) {
        String event = switch (request.decision()) {
            case APPROVE -> "CLAIM_APPROVED";
            case REJECT -> "CLAIM_REJECTED";
            case NONE -> switch (claim.getStatus()) {
                case OPEN -> "CLAIM_OPENED";
                case PENDING -> "CLAIM_PENDING";
                case SETTLED -> "CLAIM_SETTLED";
                case VOID -> "CLAIM_VOIDED";
                case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
            };
        };
        net.officefloor.hq.app.person.Person person = people.find(claim.getSheetId(), claim.getPersonId());
        log.record(claim, person, request.user());
        String line = ClaimAudit.line(event, request.user(), person, claim, number.value());
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            line += " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
        }
        if (request.decision() == ValidClaimStatus.Decision.REJECT) {
            line += " reason=" + request.reason();
        }
        audit.recordOnCommit(line);
        rollup.recordChanges(claim.getSheetId(), request.user(), before);
    }
}
package net.officefloor.hq.app.claim;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Settles the selected claims in list order (people in the order they were added, newest claim first
 * within a person), each by exactly the rules of settling one claim and audited as a single settle
 * would be. A claim that goes to PENDING counts as settled; a selected claim that cannot be settled is
 * left as it is and counted as refused; so is a selected id that is not a claim on the sheet.
 */
public class BulkSettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @RequestBody BulkSettleRequest request,
            Claims claims, Sheets sheets, People people, Rates rates, Periods periods, Settings settings,
            ClaimNumbering numbering, Rollup rollup, Audit audit, ClaimLog log,
            ObjectResponse<BulkSettleResponse> response) {
        Set<String> selected = new HashSet<>(request.claimIds() == null ? List.of() : request.claimIds());
        ValidClaimStatus settle = new ValidClaimStatus(ClaimStatus.SETTLED, request.user(),
                ValidClaimStatus.Decision.NONE, null);
        List<Claim> all = claims.list(sheetId);
        int settled = 0;
        for (Person person : people.list(sheetId)) {
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !selected.contains(String.valueOf(claim.getId()))) {
                    continue;
                }
                RollupFigures before = rollup.figures(sheetId);
                ClaimNumber number;
                try {
                    number = ApplyClaimStatus.change(settle, claim, sheets, people, rates, periods, settings, numbering);
                } catch (ClaimStatusRefusedException refused) {
                    continue;
                }
                claims.save(claim);
                AuditClaimStatus.record(settle, claim, number, people, audit, before, rollup, log);
                settled++;
            }
        }
        response.send(new BulkSettleResponse(settled, selected.size() - settled));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Re-settles a SETTLED claim; only a steward re-settles, and not a claim dated inside a closed period.
 * The settled due is frozen again at the figure the claim would have today as an open claim bound by no
 * statement: its amount (raised to the floor) at the rate of its person's grade in force on its date,
 * with its late charge as of today on top.
 */
public class ApplyResettle {
    public void apply(@Val ResettleRequest request, @Val Claim claim, Sheets sheets, People people, Rates rates,
            Periods periods, Settings settings, Out<ClaimResettle> resettle) throws ClaimStatusRefusedException {
        String sheetId = claim.getSheetId();
        if (!Settings.STEWARD.equals(settings.role(sheetId, request.user()))) {
            throw new ClaimStatusRefusedException("Only a steward can re-settle a claim");
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ClaimStatusRefusedException("Only a SETTLED claim can be re-settled");
        }
        if (periods.isClosed(sheetId, claim.getDate())) {
            throw new ClaimStatusRefusedException("No claim dated inside a closed period can be re-settled");
        }
        RoundingMode rounding = Rounding.of(claim, settings.policyDate(sheetId));
        String grade = people.find(sheetId, claim.getPersonId()).gradeOn(claim.getDate());
        BigDecimal figure = Rates.due(claim.getAmount(), rates.find(sheetId, grade, claim.getDate()),
                settings.floor(sheetId, claim.getDate()), rounding);
        BigDecimal due = figure == null ? null
                : figure.add(LateCharge.asOpen(claim, figure, on -> settings.latePct(sheetId, on), sheets.today(sheetId), rounding));
        BigDecimal old = claim.getSettledDue();
        claim.setSettledDue(due);
        resettle.set(new ClaimResettle(old, due));
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is rolled back
     * (refused by a later step) writes no line. Outside a transaction it is appended at once.
     */
    public void recordOnCommit(String entry) {
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
                @Override
                public void afterCommit() {
                    record(entry);
                }
            });
        } else {
            record(entry);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
