package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPeople {
    public void service(@PathVariable("sheetId") String sheetId, People people,
            ObjectResponse<List<PersonResponse>> response) {
        response.send(PersonResponse.from(people.list(sheetId)));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date (the sheet's today when blank). Their claims keep counting. */
public class RetirePerson {
    public void retire(@Val ValidRetire request, @Val Person person, People people, Sheets sheets, Audit audit) {
        LocalDate from = request.date() != null ? request.date() : sheets.today(person.getSheetId());
        person.setRetiredFrom(from);
        people.saveRetired(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + person.getSheetId() + " by=" + request.user()
                + " name=" + person.getName() + " from=" + from);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateRetire {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody RetireRequest request, Out<ValidRetire> body, Settings settings)
            throws InvalidPersonException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String raw = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!raw.isEmpty()) {
            try {
                date = LocalDate.parse(raw);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The retirement date is not a date");
            }
        }
        body.set(new ValidRetire(date, request.user()));
    }
}
